insert into public.pasos_zona (nivel_id, orden, titulo, detalle, segundos) values
(1,1,'Calentamiento','Con la palma o las yemas de los dedos, desliza suavemente sobre toda la zona en movimientos largos y livianos, sin presionar fuerte todavía — esto prepara el tejido y hace la técnica siguiente más efectiva y menos molesta.',20),
(1,2,'Ubicar el punto','Sentada, con los brazos relajados, coloca las yemas de los dedos entre el cuello y el hombro. Este punto suele generar dolor referido hacia la sien o detrás del ojo.',20),
(1,3,'Presión en círculos','Presiona firme, en círculos pequeños, sobre el punto más tenso.',30),
(1,4,'Estiramiento de cierre','Lleva la oreja hacia el hombro (sin subir el hombro) y sostén.',20),
(2,1,'Calentamiento','Con la palma o las yemas de los dedos, desliza suavemente sobre toda la zona en movimientos largos y livianos, sin presionar fuerte todavía — esto prepara el tejido y hace la técnica siguiente más efectiva y menos molesta.',20),
(2,2,'Postura','Sentada, inclina la cabeza levemente hacia el lado contrario al que vas a trabajar, para exponer mejor el borde del músculo.',20),
(2,3,'Presión en el borde','Con las yemas de los dedos, presiona en círculos pequeños sobre el borde lateral del trapecio, cerca del cuello. Este punto suele referir dolor hacia la mandíbula y la oreja.',45),
(2,4,'Estiramiento de cierre','Lleva la oreja hacia el hombro contrario y sostén.',20),
(3,1,'Calentamiento','Con la palma o las yemas de los dedos, desliza suavemente sobre toda la zona en movimientos largos y livianos, sin presionar fuerte todavía — esto prepara el tejido y hace la técnica siguiente más efectiva y menos molesta.',20),
(3,2,'Postura','Sentada, lleva el brazo del lado a trabajar cruzado hacia el pecho, para separar el omóplato y exponer el trapecio medio.',15),
(3,3,'Presión sostenida','Con los dedos de la otra mano, presiona el punto entre los omóplatos. Suele generar una sensación de ardor en esa zona media de la espalda.',60),
(3,4,'Soltar despacio','Suelta la presión lentamente y respira hondo dos veces.',20),
(4,1,'Calentamiento','Con la palma o las yemas de los dedos, desliza suavemente sobre toda la zona en movimientos largos y livianos, sin presionar fuerte todavía — esto prepara el tejido y hace la técnica siguiente más efectiva y menos molesta.',20),
(4,2,'Postura','Acostada boca abajo o sentada inclinada hacia adelante, con el brazo relajado colgando, para acceder a la parte más baja del trapecio.',15),
(4,3,'Presión profunda','Nivel avanzado: presiona el punto más bajo, cerca del borde interno del omóplato, con presión más sostenida y profunda. Baja la intensidad de inmediato si duele demasiado.',90),
(4,4,'Estiramiento de cierre','Lleva la oreja hacia el hombro contrario y sostén.',20),
(5,1,'Calentamiento','Con la palma o las yemas de los dedos, desliza suavemente sobre toda la zona en movimientos largos y livianos, sin presionar fuerte todavía — esto prepara el tejido y hace la técnica siguiente más efectiva y menos molesta.',20),
(5,2,'Punto básico','Yemas de los dedos entre cuello y hombro, presión en círculos.',60),
(5,3,'Borde lateral','Presión en círculos sobre el borde lateral del trapecio.',60),
(5,4,'Punto medio','Presión sostenida en el punto entre los omóplatos.',60),
(5,5,'Punto profundo','Presión más profunda y sostenida en la parte baja del trapecio.',60),
(5,6,'Estiramiento de cierre','Lleva la oreja hacia cada hombro y sostén, respirando lento.',30),
(6,1,'Calentamiento','Con las yemas de los dedos, desliza suavemente por toda la nuca en movimientos largos y livianos, sin presionar fuerte todavía.',20),
(6,2,'Ubicar el borde óseo','Busca con los dedos el borde justo donde termina el cráneo y empieza el cuello, a los costados de la columna.',20),
(6,3,'Presión sostenida con los dedos','Presiona sosteniendo con las yemas de los dedos, moviendo la cabeza suavemente en ''sí'' y ''no'' para encontrar el punto exacto.',60),
(6,4,'Cierre con las palmas','Con las palmas de ambas manos, envuelve la base del cráneo y sostén una presión suave y constante, como un pequeño abrazo.',20),
(7,1,'Calentamiento','Con las yemas de los dedos, desliza suavemente por toda la nuca.',20),
(7,2,'Ubicar el borde óseo','Vuelve al borde donde termina el cráneo, esta vez sosteniendo un poco más de tiempo en cada punto.',20),
(7,3,'Presión sostenida','Presiona con las yemas de los dedos, un poco más firme que la vez anterior, moviendo la cabeza suavemente.',75),
(7,4,'Cierre con las palmas','Envuelve la base del cráneo con las palmas y sostén.',20),
(8,1,'Calentamiento','Desliza suavemente por toda la nuca con las yemas de los dedos.',20),
(8,2,'Ubicar el punto lateral','Busca un poco más hacia el lado, cerca de la base del cráneo. Este punto suele referir dolor hacia la sien del mismo lado.',20),
(8,3,'Presión sostenida','Sostén la presión con las yemas de los dedos, respirando lento.',60),
(8,4,'Cierre','Envuelve la base del cráneo con las palmas y suelta despacio.',20),
(9,1,'Calentamiento','Desliza suavemente por toda la nuca.',20),
(9,2,'Ubicar el mismo punto lateral','Vuelve al punto lateral del nivel anterior.',15),
(9,3,'Presión profunda y sostenida','Nivel avanzado: presiona más profundo y sostén más tiempo. Baja la intensidad si sientes mareo o dolor que se dispara.',90),
(9,4,'Cierre con las palmas','Envuelve la base del cráneo y sostén, respirando hondo.',20),
(10,1,'Calentamiento','Desliza suavemente por toda la nuca.',20),
(10,2,'Lado 1','Presión sostenida en el borde óseo y el punto lateral de un lado.',75),
(10,3,'Lado 2','Repite del otro lado.',75),
(10,4,'Estiramiento de cierre','Envuelve la base del cráneo con ambas palmas y sostén, respirando lento.',30),
(11,1,'Calentamiento','Con la palma o las yemas de los dedos, desliza suavemente sobre toda la zona en movimientos largos y livianos, sin presionar fuerte todavía — esto prepara el tejido y hace la técnica siguiente más efectiva y menos molesta.',20),
(11,2,'Ubicar el músculo temporal','Coloca las yemas de los dedos por encima de la oreja, en la sien.',15),
(11,3,'Círculos lentos','Presión circular lenta desde la línea del cabello hacia adelante, hasta la esquina externa del ojo.',60),
(11,4,'Combinar con mandíbula','Este trabajo es más efectivo si se combina con el automasaje de mandíbula.',30),
